{
  "name": "realpath-resolver",
  "version": "1.0.0",
  "description": "Resolve symlinks to a canonical filesystem path, consistently across Node versions.",
  "main": "index.js",
  "type": "commonjs",
  "scripts": {
    "start": "node index.js",
    "test": "node test.js"
  },
  "license": "MIT"
}

'use strict';

const fs = require('fs');

function toRealPath(inputPath) {
  return fs.realpathSync(inputPath);
}

function main() {
  const target = process.argv[2];
  if (!target) {
    console.error('Usage: node index.js <path>');
    process.exitCode = 1;
    return;
  }
  process.stdout.write(toRealPath(target) + '\n');
}

if (require.main === module) {
  main();
}

module.exports = { toRealPath };

'use strict';

const assert = require('assert');
const fs = require('fs');
const os = require('os');
const path = require('path');

const { toRealPath } = require('./index');

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'realpath-'));
const realFile = path.join(tmp, 'real.txt');
const linkFile = path.join(tmp, 'link.txt');

fs.writeFileSync(realFile, 'hello');
fs.symlinkSync(realFile, linkFile);

try {
  assert.strictEqual(toRealPath(linkFile), fs.realpathSync(realFile));
  console.log('ok');
} finally {
  fs.rmSync(tmp, { recursive: true, force: true });
}
